@import url('https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Cash App DNA — pure black, electric green, heavy condensed type */
.theme-cash-app-dna {
  --bg: oklch(0 0 0);
  --surface: oklch(0.14 0 0);
  --surface-2: oklch(0.2 0 0);
  --fg: oklch(0.99 0 0);
  --fg-muted: oklch(0.68 0 0);
  --accent: oklch(0.761 0.245 144.3);
  --accent-fg: oklch(0.000 0 0);
  --accent-2: oklch(0.72 0.2 148);
  --line: oklch(0.3 0 0);
  --success: oklch(0.85 0.24 148);
  --warning: oklch(0.85 0.18 90);
  --danger: oklch(0.65 0.24 25);

  --radius: 1rem;
  --radius-sm: 0.75rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;

  --shadow-1: 0 0 0 1px oklch(1 0 0 / 6%);
  --shadow-2: 0 8px 24px -12px oklch(0.85 0.24 148 / 35%);
  --shadow-3: 0 0 48px -12px oklch(0.85 0.24 148 / 45%);
  --glow: 0 0 0 3px color-mix(in oklab, var(--accent) 45%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Anton", "Arial Black", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.03em;
  --label-transform: uppercase;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-cash-app-dna h1,
.theme-cash-app-dna h2,
.theme-cash-app-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 400;
  text-transform: uppercase;
  line-height: 0.95;
  font-stretch: condensed;
}

.theme-cash-app-dna button {
  font-weight: 700;
  letter-spacing: 0.02em;
}

/* signature */
.theme-cash-app-dna { --font-ui: var(--font-display); }
.theme-cash-app-dna h1 { text-transform: uppercase; transform: skewX(-4deg); display: inline-block; }
.theme-cash-app-dna button { text-transform: uppercase; letter-spacing: 0.04em; }
.theme-cash-app-dna button:hover { box-shadow: 0 0 24px color-mix(in oklab, var(--accent) 60%, transparent); }

/* depth */
.theme-cash-app-dna thead th { font-family: var(--font-display); font-weight: 400; text-transform: uppercase; letter-spacing: 0.06em; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-cash-app-dna td { border-bottom: 1px solid var(--line); font-variant-numeric: tabular-nums; }
.theme-cash-app-dna tbody tr:hover { background: color-mix(in oklab, var(--accent) 7%, var(--surface)); }
.theme-cash-app-dna input, .theme-cash-app-dna select, .theme-cash-app-dna textarea { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); transition: border-color 120ms ease, box-shadow 120ms ease; }
.theme-cash-app-dna input:focus-visible, .theme-cash-app-dna select:focus-visible, .theme-cash-app-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-cash-app-dna a { color: var(--accent); text-decoration: none; font-weight: 600; }
.theme-cash-app-dna a:hover { text-decoration: underline; text-underline-offset: 3px; text-shadow: 0 0 12px color-mix(in oklab, var(--accent) 55%, transparent); }
.theme-cash-app-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-cash-app-dna ::-webkit-scrollbar { width: 8px; }
.theme-cash-app-dna ::-webkit-scrollbar-track { background: var(--bg); }
.theme-cash-app-dna ::-webkit-scrollbar-thumb { background: var(--surface-2); border-radius: 999px; }
.theme-cash-app-dna ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-cash-app-dna kbd { font-family: var(--font-mono); font-size: 0.72em; color: var(--accent); background: var(--surface); border: 1px solid var(--line); border-radius: 6px; padding: 0.1em 0.45em; }
.theme-cash-app-dna .label-caps { font-family: var(--font-display); letter-spacing: 0.08em; }
.theme-cash-app-dna .themed-border { border-color: var(--line); }
.theme-cash-app-dna button:active { transform: scale(0.96); }

/* alt mode: auto-derived light variant */
.theme-cash-app-dna.alt-mode {
  --bg: oklch(0.98 0.000 0.0);
  --surface: oklch(0.955 0.000 0.0);
  --surface-2: oklch(0.92 0.000 0.0);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --accent: oklch(0.60 0.21 144.3);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.52 0.17 148);
  --success: oklch(0.56 0.19 148);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
